var n=0
let r:Result<int,unit>=Err(tick(&mut n))
return match r {Ok(v)=>v,Err(_)=>n+41}

let n=Some(41)
let x:Option<int>=Option<int>.Some(n)
return match x {Some(v)=>v,None=>0}

let r:Result<owned buffer,owned buffer>=Err(buffer(3))
let n=match &r {Ok(p)=>bufferSize(p),Err(p)=>bufferSize(p)}
return match r {Ok(p)=>bufferLength(p),Err(p)=>bufferLength(p)*10+n}

let x:Result<Option<Empty>,Empty>=Ok(Some(Empty()))
let y=x
let z:Result<Option<Empty>,Empty>=Err(Empty())
let n:Option<Empty>=None
let a=match x {Ok(o)=>match o {Some(e)=>take(e),None=>0},Err(_)=>0}
let b=match y {Ok(o)=>match o {Some(e)=>take(e),None=>0},Err(_)=>0}
let c=match z {Ok(_)=>0,Err(e)=>take(e)}
return a+b+c+(match n {Some(_)=>0,None=>42})-126

